config.chat_template_jinja:
{%- macro value(v) -%}
    {%- if v is mapping -%}
        {%- for k, item in v.items() -%}{{ argument(k, item) }}{%- endfor -%}
    {%- elif v is sequence and v is not string -%}
        {%- for item in v -%}{{ argument(loop.index0 | string, item) }}{%- endfor -%}
    {%- elif v is none -%}null
    {%- elif v is sameas true -%}true
    {%- elif v is sameas false -%}false
    {%- else -%}{{ v }}
    {%- endif -%}
{%- endmacro -%}
{%- macro argument(name, v) -%}
    {{- '<|tool_argument|><|tool_argument_name|>' ~ name ~ '<|tool_argument_name_end|><|tool_argument_value|>' -}}
    {{- value(v) -}}
    {{- '<|tool_argument_value_end|><|tool_argument_end|>' -}}
{%- endmacro -%}
{%- macro metadata(label, obj, excluded) -%}
    {%- set ns = namespace(started=false) -%}
    {%- for k, v in obj.items() if k not in excluded -%}
        {%- if not ns.started -%}{{ '\n' ~ label ~ ':\n' }}{%- set ns.started = true -%}{%- endif -%}
        {{- argument(k, v) -}}
    {%- endfor -%}
{%- endmacro -%}
{%- macro definitions(items) -%}
    {%- if items is string or items is mapping -%}
        {{- raise_exception('Tool definitions must be a list of objects; decode JSON before applying the template.') -}}
    {%- endif -%}
    {%- for definition in items -%}
        {%- set f = definition.get('function', definition) -%}
        {{- '<|tool_name|>' ~ f['name'] ~ '<|tool_name_end|>' -}}
        {%- if 'description' in f -%}{{ '\nDescription:\n' }}{{ value(f['description']) }}{%- endif -%}
        {%- set params = f.get('parameters', {}) -%}
        {{- '<|tool_arguments|>' -}}
        {%- for name, schema in params.get('properties', {}).items() -%}
            {{- '<|tool_argument|><|tool_argument_name|>' ~ name ~ '<|tool_argument_name_end|>' -}}
            {%- if schema is mapping -%}
                {%- if 'type' in schema -%}{{ '<|tool_argument_type|>' }}{{ value(schema['type']) }}{{ '<|tool_argument_type_end|>' }}{%- endif -%}
                {%- if 'description' in schema -%}{{ '\nDescription:\n' }}{{ value(schema['description']) }}{%- endif -%}
                {%- for key in ['example', 'examples'] if key in schema -%}
                    {{- key ~ ':<|tool_argument_example|>' -}}{{ value(schema[key]) }}{{ '<|tool_argument_example_end|>' }}
                {%- endfor -%}
                {{- metadata('Constraints', schema, ['type', 'description', 'example', 'examples']) -}}
            {%- else -%}{{ '\nConstraints:\n' }}{{ value(schema) }}
            {%- endif -%}
            {{- '<|tool_argument_end|>' -}}
        {%- endfor -%}
        {{- metadata('Parameter constraints', params, ['properties']) -}}
        {{- metadata('Function metadata', f, ['name', 'description', 'parameters']) -}}
        {%- if 'function' in definition -%}{{ metadata('Tool metadata', definition, ['function']) }}{%- endif -%}
    {%- endfor -%}
{%- endmacro -%}
{%- set roles = {'system': '<|im_system|>', 'user': '<|im_human|>', 'assistant': '<|im_model|>', 'tool': '<|im_tool_response|>', 'environment': '<|im_tool_response|>'} -%}
{%- set supplied_tools = tools | default([], true) -%}
{%- if supplied_tools and (not messages or messages[0]['role'] != 'system') -%}
    {{- '<|im_system|>' -}}{{ definitions(supplied_tools) }}{{ '<|im_end|>' }}
{%- endif -%}
{%- for message in messages -%}
    {%- set role = message['role'] -%}
    {%- if role not in roles -%}{{ raise_exception('Unsupported message role: ' ~ role) }}{%- endif -%}
    {%- set calls = message.get('tool_calls') or message.get('function_calls') or [] -%}
    {%- if calls is string or calls is mapping -%}
        {{- raise_exception('Tool calls must be structured objects with dictionary arguments; parse raw Dolci function_calls first.') -}}
    {%- endif -%}
    {%- if calls and role != 'assistant' -%}{{ raise_exception('Only assistant messages may contain tool calls.') }}{%- endif -%}
    {%- set defs = message.get('functions') or [] -%}
    {%- if supplied_tools and loop.first and role == 'system' -%}
        {%- if defs -%}{{ raise_exception('Supply tools globally or on the first system message, not both.') }}{%- endif -%}
        {%- set defs = supplied_tools -%}
    {%- endif -%}
    {%- if defs and role != 'system' -%}{{ raise_exception('Tool definitions require a system message.') }}{%- endif -%}
    {%- set content = message.get('content') -%}
    {%- if content is none and (calls or defs or message.get('reasoning_content') is not none) -%}{%- set content = '' -%}{%- endif -%}
    {%- if content is not string -%}{{ raise_exception('Message content must be a string.') }}{%- endif -%}
    {%- if defs -%}
        {%- set content = content.replace('within <functions></functions> XML tags', 'in the tool definitions below').replace('within <functions></functions>', 'in the tool definitions below') -%}
        {%- set call_hint = '<|tool_call|><|tool_name|>NAME<|tool_name_end|><|tool_arguments|>ARGUMENTS<|tool_call_end|> delimiters' -%}
        {%- set content = content.replace('<function_calls></function_calls> XML tags', call_hint).replace('<function_calls></function_calls>', call_hint) -%}
    {%- endif -%}
    {{- roles[role] -}}
    {%- if role == 'assistant' and message.get('reasoning_content') is not none -%}
        {%- if message['reasoning_content'] is not string -%}{{ raise_exception('reasoning_content must be a string.') }}{%- endif -%}
        {{- '<|think|>' ~ message['reasoning_content'].strip('\r\n') ~ '<|think_end|>' ~ content.lstrip('\r\n') -}}
    {%- elif role == 'assistant' and parse_reasoning_tags | default(false) and (content or not calls) -%}
        {%- set body = content.lstrip() -%}
        {%- if not body.startswith('<think>') or body.count('<think>') != 1 or body.count('</think>') != 1 -%}
            {{- raise_exception('Expected one leading <think>...</think> block.') -}}
        {%- endif -%}
        {%- set prefix = content[:(content | length) - (body | length)] -%}
        {%- set chunks = body[7:].split('</think>') -%}
        {{- prefix.replace('\r', '').replace('\n', '') ~ '<|think|>' ~ chunks[0].strip('\r\n') ~ '<|think_end|>' ~ chunks[1].lstrip('\r\n') -}}
    {%- else -%}{{ content }}
    {%- endif -%}
    {%- if defs -%}{{ definitions(defs) }}{%- endif -%}
    {%- for call in calls -%}
        {%- set f = call.get('function', call) -%}
        {%- set args = f.get('arguments', {}) -%}
        {%- if args is not mapping -%}{{ raise_exception('Tool arguments must be a dictionary, not JSON text.') }}{%- endif -%}
        {{- '<|tool_call|><|tool_name|>' ~ f['name'] ~ '<|tool_name_end|><|tool_arguments|>' -}}
        {{- value(args) -}}{{ '<|tool_call_end|>' }}
    {%- endfor -%}
    {{- '<|im_end|>' -}}
{%- endfor -%}
{%- if add_generation_prompt -%}
    {{- '<|im_model|>' -}}
    {%- if enable_thinking | default(false) -%}{{ '<|think|>' }}{%- endif -%}
{%- endif -%}
